// Pull out sender, subject and text. Skip automatic emails so we never reply to a robot.
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const fromRaw = typeof m.from === 'string' ? m.from : (m.from?.text || m.from?.value?.[0]?.address || '');
  const emailMatch = fromRaw.match(/[\w.+'-]+@[\w-]+(\.[\w-]+)+/);
  if (!emailMatch) continue;
  const email = emailMatch[0].toLowerCase();
  const name = fromRaw.replace(/<.*>/, '').replace(/"/g, '').trim();
  if (/(no-?reply|mailer-daemon|postmaster|notifications?@|bounce)/i.test(email)) continue;
  const autoSubmitted = m.metadata?.['auto-submitted'];
  if (autoSubmitted && autoSubmitted !== 'no') continue; // out-of-office and other automatic replies

  const subject = m.subject || '';
  const text = String(m.textPlain || m.text || m.textHtml || m.html || '')
    .replace(/<[^>]+>/g, ' ')
    .slice(0, 8000);
  const firstLine = text.trim().split('\n')[0].trim();
  const unsubscribe = /^(stop|unsubscribe)\b/i.test(firstLine) || /^(stop|unsubscribe)$/i.test(subject.trim());

  out.push({ json: { email, name: name === email ? '' : name, subject, text, unsubscribe } });
}
return out;

