parameters.jsCode:
const c = $json;
const mail = $('Read email').item.json;

const SYSTEM = "You answer customer emails for a luxury watch dealer (new and pre-owned). Reply in the customer's language, warmly and professionally, like a knowledgeable sales assistant. Use ONLY the stock list you are given for availability, prices and details; if a watch is not in stock, say so and offer to notify them when one arrives. Never invent watches, prices, discounts, delivery dates or guarantees. You are NOT allowed to: negotiate or promise discounts, discuss payment methods or bank details, issue receipts or invoices, or agree to a sale. When the email is about any of these, or the deal is large, set needs_human=true, and write a short polite reply saying a specialist will personally contact them shortly. Plain text only, no markdown. Sign with the business name. language = ISO 639-1 code of the customer's language. interests = watches the customer shows interest in (brand, and reference if known, else empty string). estimated_deal_usd = value of what they want to buy, 0 if unknown. is_spam_or_automated = true for spam, newsletters, auto-replies.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "language": {
      "type": "string"
    },
    "reply_subject": {
      "type": "string"
    },
    "reply_body": {
      "type": "string"
    },
    "needs_human": {
      "type": "boolean"
    },
    "human_reason": {
      "type": "string"
    },
    "estimated_deal_usd": {
      "type": "number"
    },
    "interests": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "brand": {
            "type": "string"
          },
          "reference": {
            "type": "string"
          }
        },
        "required": [
          "brand",
          "reference"
        ],
        "additionalProperties": false
      }
    },
    "is_spam_or_automated": {
      "type": "boolean"
    }
  },
  "required": [
    "language",
    "reply_subject",
    "reply_body",
    "needs_human",
    "human_reason",
    "estimated_deal_usd",
    "interests",
    "is_spam_or_automated"
  ],
  "additionalProperties": false
};
const userContent = `Business name: ${c.business_name}
Customer: ${c.name || 'unknown name'} <${c.email}>
Known language: ${c.language}
Past purchases: ${c.past_purchases || 'none'}
Known interests: ${c.known_interests || 'none'}

Stock list (JSON):
${JSON.stringify(c.inventory || [])}

Customer email:
Subject: ${mail.subject}
${mail.text}`;

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'medium',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

const c = $('Save customer + load context').item.json;
const mail = $('Read email').item.json;

// Safety net on top of Claude: these topics ALWAYS go to a human.
const HUMAN_TOPICS = /(payment|pay |bank|wire|transfer|iban|swift|invoice|receipt|deposit|crypto|discount|best price|negotiat|offer you|lower price|final price)/i;
const bigDeal = Number(ai.estimated_deal_usd || 0) >= Number(c.large_deal_usd);
const needsHuman = ai.needs_human || bigDeal || HUMAN_TOPICS.test(mail.subject + ' ' + mail.text);
const autoSend = String(c.auto_send_replies).toLowerCase() === 'true';

let reason = ai.human_reason;
if (bigDeal) reason = `Large deal (about $${Math.round(ai.estimated_deal_usd)}). ` + (reason || '');
if (!ai.needs_human && needsHuman && !bigDeal) reason = 'Mentions payment, discount or negotiation. ' + (reason || '');

return {
  json: {
    customer_id: c.customer_id,
    customer_email: c.email,
    customer_name: c.name,
    owner_email: c.owner_email,
    from_email: c.from_email,
    subject: mail.subject,
    body: mail.text,
    language: ai.language,
    interests: ai.interests,
    reply_subject: ai.reply_subject || ('Re: ' + mail.subject),
    reply_body: ai.reply_body,
    needs_human: needsHuman,
    human_reason: needsHuman ? (reason || '') : '',
    // what to do next
    send_to_customer: !ai.is_spam_or_automated && autoSend,
    notify_owner: !ai.is_spam_or_automated && (needsHuman || !autoSend),
    status: ai.is_spam_or_automated ? 'ignored' : (autoSend ? 'auto_sent' : 'sent_to_owner'),
  },
};

// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const d = $('Decide: send or hand to human').item.json;
return {
  json: {
    owner_email: d.owner_email,
    from_email: d.from_email,
    subject: `${d.needs_human ? 'ACTION NEEDED' : 'Draft reply'}: ${d.customer_name || d.customer_email} - ${d.subject}`,
    html: `<p><b>${d.needs_human ? 'A human must handle this: ' + esc(d.human_reason) : 'Automatic sending is off. Review and send this draft.'}</b></p>
<p>Customer: ${esc(d.customer_name)} &lt;${esc(d.customer_email)}&gt;</p>
<h4>Customer wrote</h4><p style="white-space:pre-wrap">${esc(d.body)}</p>
<h4>${d.send_to_customer ? 'Holding reply already sent' : 'Suggested reply (not sent)'}</h4>
<p style="white-space:pre-wrap">${esc(d.reply_body)}</p>`,
  },
};
